  const m1 = new Matrix([[1, 2], [3, 4]]);
  m1.add("not a matrix");
  console.log("Test 3 - Non-Matrix operand: FAIL - Should have thrown error");
} catch (e) {
  console.log("Test 3 - Non-Matrix operand: PASS -", e.message);
}

