  const m1 = new Matrix([[1, 2], [3, 4]]);
  const m2 = new Matrix([[5, 6, 7], [8, 9, 10]]);
  m1.sub(m2);
  console.log("Test 5 - Subtraction shape mismatch: FAIL - Should have thrown error");
} catch (e) {
  console.log("Test 5 - Subtraction shape mismatch: PASS -", e.message);
}

