try {
  const m1 = new Matrix([[1, 2], [3, 4]]);
  const m2 = new Matrix([[5, 6], [7, 8]]);
  const original1 = m1.toArray();
  const original2 = m2.toArray();
  m1.add(m2);
  const after1 = m1.toArray();
  const after2 = m2.toArray();

